def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = next(c for c in range(w) if len({row[c] for row in grid}) == 1)
    n = min(sep, w - sep - 1)

    def background(cells):
        counts = {}
        for value in cells:
            counts[value] = counts.get(value, 0) + 1
        return max(counts, key=counts.get)

    left_bg = background([grid[r][c] for r in range(h) for c in range(sep)])
    right_bg = background([grid[r][c] for r in range(h) for c in range(sep + 1, w)])

    out = [[4] * n for _ in range(h)]
    for r in range(h):
        for c in range(n):
            if grid[r][c] != left_bg and grid[r][sep + 1 + c] != right_bg:
                out[r][c] = 3
    return out
